// flag, so there is never a word boundary after a Cyrillic unit word.
const UNIT_RE =
  /\d+(?:[.,]\d+)?(?:\s*(?:кг|г|шт|мл|л))?(?:\s*-\s*\d+(?:[.,]\d+)?)?\s*(?:кг|г|шт|мл|л)(?![\p{L}\p{N}])/u;

const NAMED_ENTITIES: Record<string, string> = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  apos: "'",
  nbsp: " ",
  laquo: "«",
  raquo: "»",
  mdash: "—",
  ndash: "–",
  hellip: "…",
};

